<?php require_once '../config/auth.php';require_admin();$action=$_POST['action']??$_GET['action']??'';try{if($action==='create'){$s=$pdo->prepare('INSERT INTO categories(name) VALUES(?)');$s->execute([trim($_POST['name'])]);}elseif($action==='update'){$s=$pdo->prepare('UPDATE categories SET name=? WHERE id=?');$s->execute([trim($_POST['name']),(int)$_POST['id']]);}elseif($action==='delete'){$s=$pdo->prepare('DELETE FROM categories WHERE id=?');$s->execute([(int)$_GET['id']]);}header('Location: ../kategori.php');}catch(Throwable $e){http_response_code(400);echo 'Gagal: '.e($e->getMessage()).' <br><a href="../kategori.php">Kembali</a>';}
